def min_capacity(sizes, days):
    def days_needed(cap):
        d, load = 1, 0
        for s in sizes:
            if load + s > cap:
                d += 1
                load = 0
            load += s
        return d
    lo, hi = max(sizes), sum(sizes)
    while lo < hi:
        mid = (lo + hi) // 2
        if days_needed(mid) <= days:
            hi = mid
        else:
            lo = mid + 1
    return lo

