    out = []
    i = j = 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i])
            i += 1
        else:
            out.append(b[j])
            j += 1
    return out + a[i:] + b[j:]


def merge_k(lists):
    if not lists:
        return []
    while len(lists) > 1:
        nxt = []
        for i in range(0, len(lists), 2):
            if i + 1 < len(lists):
                nxt.append(merge(lists[i], lists[i + 1]))
            else:
                nxt.append(lists[i])
        lists = nxt
    return list(lists[0])

