def find_trade(ring, seq):
    lo, hi = 0, len(ring) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if ring[mid] == seq:
            return mid
        if ring[lo] <= ring[mid]:            # slots lo to mid are in order
            if ring[lo] <= seq < ring[mid]:
                hi = mid - 1
            else:
                lo = mid + 1
        else:                                # slots mid to hi are in order
            if ring[mid] < seq <= ring[hi]:
                lo = mid + 1
            else:
                hi = mid - 1
    return -1

