def ring_sweep(top=12):
    misses, first = 0, None
    for n in range(top + 1):
        base = [3 * i + 1 for i in range(n)]
        for k in range(max(n, 1)):
            ring = base[k:] + base[:k]
            for seq in range(3 * n + 2):
                want = ring.index(seq) if seq in ring else -1
                try:
                    got = find_trade(list(ring), seq)
                except Exception as err:
                    got = type(err).__name__
                if got != want:
                    misses += 1
                    if first is None:
                        first = [ring, seq, got]
    return [misses, first]
